{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if set(case) - {'nodes', 'required_symbols', '_case_nonce'}:
        raise ValueError('unexpected case field')
    nodes = case.get('nodes')
    required = case.get('required_symbols')
    if not isinstance(nodes, list) or not nodes:
        raise ValueError('nodes must be a nonempty list')
    if not isinstance(required, list) or any(not isinstance(x, str) for x in required):
        raise ValueError('required_symbols must be a list of strings')
    if len(set(required)) != len(required):
        raise ValueError('required_symbols must be unique')

    by_id = {}
    children = {}
    for node in nodes:
        if not isinstance(node, dict) or set(node) != {'id', 'parent', 'symbol', 'depth', 'removable', 'utility'}:
            raise ValueError('invalid node fields')
        node_id = node['id']
        parent = node['parent']
        if (not isinstance(node_id, str) or not node_id or node_id in by_id or
                (parent is not None and (not isinstance(parent, str) or not parent)) or
                not isinstance(node['symbol'], str) or not node['symbol'] or
                isinstance(node['depth'], bool) or not isinstance(node['depth'], int) or node['depth'] < 0 or
                not isinstance(node['removable'], bool) or
                isinstance(node['utility'], bool) or not isinstance(node['utility'], (int, float))):
            raise ValueError('invalid node value')
        utility = node['utility']
        if utility != utility or utility in (float('inf'), float('-inf')):
            raise ValueError('utility must be finite')
        by_id[node_id] = node
        children[node_id] = []

    roots = []
    for node in nodes:
        node_id = node['id']
        parent = node['parent']
        if parent is None:
            roots.append(node_id)
            if node['depth'] != 0:
                raise ValueError('root depth must be zero')
        else:
            if parent not in by_id:
                raise ValueError('unknown parent')
            if node['depth'] != by_id[parent]['depth'] + 1:
                raise ValueError('invalid depth')
            children[parent].append(node_id)
    if len(roots) != 1:
        raise ValueError('tree must have exactly one root')
    root = roots[0]

    seen = set()
    stack = [root]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            raise ValueError('tree contains a cycle')
        seen.add(node_id)
        stack.extend(children[node_id])
    if len(seen) != len(nodes):
        raise ValueError('tree is disconnected')
    symbols = {node['symbol'] for node in nodes}
    if any(symbol not in symbols for symbol in required):
        raise ValueError('required symbol is absent')

    retained = set(by_id)
    removal_order = []
    while True:
        candidates = []
        for node_id in retained:
            node = by_id[node_id]
            if node_id == root or not node['removable'] or node['symbol'] in required:
                continue
            if any(child in retained for child in children[node_id]):
                continue
            remaining_symbols = {by_id[x]['symbol'] for x in retained if x != node_id}
            if all(symbol in remaining_symbols for symbol in required):
                candidates.append(node_id)
        if not candidates:
            break
        chosen = min(candidates, key=lambda x: (-by_id[x]['depth'], x))
        retained.remove(chosen)
        removal_order.append(chosen)

    retained_ids = sorted(retained)
    return {
        'retained_ids': retained_ids,
        'removal_order': removal_order,
        'grammar_valid': True,
        'interestingness_preserved': True,
        'registered_candidate_order': removal_order[:],
        'stable_ties': True,
        'retained_utility': sum(by_id[node_id]['utility'] for node_id in retained_ids),
        'removed_utility': sum(by_id[node_id]['utility'] for node_id in removal_order),
    }
